def log_function(wrapped_function):
    @wraps(wrapped_function)
    def inner(*args, **kwargs):
        self = args[0]
        self.logger.debug(f"{wrapped_function.__name__} started")
        result = wrapped_function(*args, **kwargs)
        self.logger.debug(f"{wrapped_function.__name__} finished")
        return result

    return inner


def bts_is_on(func):
    @wraps(func)
    def inner(*args, **kwargs):
        self = args[0]
        if self._is_on:
            return func(*args, **kwargs)
        self.logger.info(f"BTS is off on PDU, {func.__name__} will not be executed")
        return

    return inner


@attr.s(cmp=False, hash=True)
class BTS(Device, metaclass=ABCMeta):
    idx = attr.ib(type=int)
    configuration = attr.ib(type=UTE_CONFIG, hash=False)
    bts_id = attr.ib(type=str)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=str)
    config_type = attr.ib(type="str")
    _user_flags = attr.ib(type=dict, hash=False)
    name = attr.ib(default="", type=str, init=False)
    suite_config_dir = attr.ib(default="", type=str, init=False)
    scfc_name = attr.ib(default=None, type=Optional[str], init=False)
    _scfc_data = attr.ib(default=None, type=dict, hash=False, init=False, repr=False)
    _scfc_path = attr.ib(default=None, type=Optional[str], init=False)
    _vendor_params = attr.ib(type=(Union[list, str, None]), default=None, init=False, hash=False)
    _rad_params = attr.ib(default=None, type=Union[list, str, None], init=False, hash=False)
    _rad_reset_required = attr.ib(default=False, type=bool, init=False, hash=False)
    _is_primary_smod = attr.ib(default=False, type=bool, init=False, hash=False)
    _is_secondary_smod = attr.ib(default=False, type=bool, init=False, hash=False)
    _sw_version = attr.ib(default="", type=str, init=False, hash=False)
    _commissioning_timeout = attr.ib(default=Timeouts.COMMISSIONING_TIMEOUT, type=int, init=False, hash=False)
    _is_on = attr.ib(default=True, type=bool, init=False, hash=False)

    def __attrs_post_init__(self):
        self.name = type(self).__name__.lower()
        self._is_on = (
            self.pdu.get_pdu_status(
                self._create_alias("check_pdu_status_on_startup"),
                self.logger,
            ).lower()
            == "on"
        )

    def set_scfc_path(self, scfc_path: str) -> None:
        self._scfc_path = scfc_path

    @cached_property
    def vlan_id(self):
        return self._get_vlan_id()

    @property
    def scfc_path(self):
        if self._scfc_path and os.path.exists(self._scfc_path):
            return self._scfc_path
        try:
            if self.scfc_name:
                if os.path.exists(self.scfc_name):
                    self._scfc_path = self.scfc_name
                else:
                    self._scfc_path = find_commissioning_filepath(self.scfc_name, self.sw_release, self.suite_config_dir, self.logger)
        except Exception as exc:
            self.logger.debug(exc, exc_info=True)
            raise

        return self._scfc_path

    @scfc_path.setter
    def scfc_path(self, value):
        self._scfc_path = value

    @property
    def scfc_data(self):
        if self._scfc_data:
            return self._scfc_data
        self._scfc_data = self._get_scfc_data()
        return self._scfc_data

    @property
    def lmp_ip(self) -> str:
        if not self._lmp_ip:
            self._lmp_ip = super().lmp_ip
            lmp_from_ping = get_pingable_lmp_ip(self._lmp_ip, ["192.168.255.129", "192.168.255.119"], self.remote_host, self.logger)
            if lmp_from_ping != self._lmp_ip:
                self.logger.info(f"Changing lmp ip to pingable one. Old: '{self._lmp_ip}' -> '{lmp_from_ping}'")
                self._lmp_ip = lmp_from_ping
        return self._lmp_ip

    @lmp_ip.setter
    def lmp_ip(self, value):
        super(BTS, self.__class__).lmp_ip.__set__(self, value)  # type: ignore[attr-defined]

    def get_rmods_count(self) -> int:
        if self.scfc_data:
            return get_rmods_num(self.scfc_data, self.logger)
        return 0

    @bts_is_on
    def configure(self):
        if self._is_secondary_smod:
            self.logger.info(f"Skipping configuration for secondary SMOD {self}")
            self.swap_lmp_for_secondary_bts()
            return
        self.update_rad_parameters()
        if self.scfc_name or self.scfc_path:
            self.perform_full_commissioning(recovery=self._user_flags["bts_recovery"])
        self.reset_if_only_rad_params()

    def _is_full_rack(self):
        return self._is_primary_smod or self._is_secondary_smod

    @bts_is_on
    def reset_config_for_full_rack(self):
        with self._get_remote_host_ssh() as ssh_connection:
            if self._is_full_rack():
                self._reset_config_and_rebot_via_ssh(ssh_connection)
                self.wait_for_interfaces_and_ssh(ssh_connection=ssh_connection)
                self._wait_for_bbus_or_smods(self._create_alias("wait_for_bbus_or_smods"))
                self._wait_until_constant_pingable(first_timeout=60, skip_reset=True, ssh_connection=ssh_connection)
            if self._is_primary_smod:
                self._perform_sync_between_smods()

    @bts_is_on
    def is_already_full_rack_config(self) -> bool:
        alias = f"is_already_full_rack_{self.remote_host}"
        with bts_admin_access(
            alias,
            self.lmp_ip,
            self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as admin_acc:
            bts_info = self._get_bts_info(alias, admin_acc, timeout=60 * 10)
            system_modules = len(bts_info.get("systemModules", []))
            self.logger.info(f"Found {system_modules} system modules.")
            if system_modules == 2:
                return True
            return False

    def _perform_sync_between_smods(self):
        alias = self._create_alias("sync_between_rmods")
        with bts_infomodel_access(alias, self.lmp_ip, self.remote_host, output_dir=self.output_directory_path, logger=self.logger) as im_acc:
            nei_obj = im_acc.get_infomodel_object("/MRBTS-*/RAT-*/RUNTIME_VIEW-*/MRBTS_R-*/NEIGHBOR_NODE_R-*", alias=alias, timeout=45)
        with bts_admin_access(
            alias,
            self.lmp_ip,
            self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as admin_acc:
            admin_acc.start_sync(nei_obj["dist_name"], alias=alias)

    def swap_lmp_for_secondary_bts(self):
        if self._is_secondary_smod:
            self.lmp_ip = "192.168.255.119"

    def _set_default_lmp_ip(self):
        self.lmp_ip = "192.168.255.129"

    def set_bts_as_primary_for_full_rack(self):
        self._is_primary_smod = True

    def set_bts_as_secondary_for_full_rack(self):
        self._is_secondary_smod = True

    def _get_scfc_data(self):
        if not self.scfc_path:
            self.scfc_path = self.download_scfc_file()

        if self.scfc_path:
            scfc_path = pathlib.Path(self.scfc_path)
            return get_dict_from_xml(scfc_path)

        self.logger.info("SCFC path not set")

        return {}

    def download_scfc_file(self):
        scfc_path = None
        try:
            scfc_dir = "/tmp"
            scfc_file_name = f"SCFC-{self.bts_id}.xml"
            alias = f"download_scfc_file_{self.remote_host}_{self.lmp_ip}"
            with bts_admin_access(
                alias=alias,
                host=self.lmp_ip,
                remote_host=self.remote_host,
                port=443,
                output_dir=self.output_directory_path,
                logger=self.logger,
                release=self.sw_release,
            ) as new_admin_connection:
                scfc_path = new_admin_connection.get_current_scf_file(
                    scfc_dir,
                    scfc_file_name,
                    connection=alias,
                    timeout=30,
                )
            self.logger.info(f"Download SCFC done for eNB {self.bts_id}!")
        except Exception as exc:
            self.logger.debug(exc, exc_info=True)

        return scfc_path

    @property
    def rad_params(self):
        return self._rad_params

    @rad_params.setter
    def rad_params(self, rad_config):
        if isinstance(rad_config, str):
            swconfig_path = pathlib.Path(rad_config)
            try:
                swconfig_is_file = swconfig_path.is_file()
            except OSError:
                swconfig_is_file = False
            if not swconfig_is_file:
                rad_config = [str(param).strip() for param in re.findall(r"([\w=]+)?[,|;]?", rad_config) if param]
            else:
                rad_config = swconfig_path
        elif isinstance(rad_config, (list, tuple)):
            rad_config = [str(param).strip() for param in rad_config]
        else:
            rad_config = None
        self._rad_params = rad_config
        self.logger.debug(f"RAD params after parsing: {self._rad_params}")

    @property
    def vendor_params(self):
        return self._vendor_params

    @vendor_params.setter
    def vendor_params(self, vendor_config: str | list[str] | None):
        self._vendor_params = parse_conf_data_to_list(vendor_config)

    def _get_lmp_ip_for_ute(self) -> str:
        try:
            self.logger.debug(f"TRS IP: {self.configuration.trs_ip}")
        except AttributeError:
            self.logger.debug("No trs_ip attribute in configuration")
        return "192.168.255.129"

    @cached_property
    def targetbd(self) -> str:
        dst_path = f"{self.output_directory_path}/targetbd.xml"
        with self._get_remote_host_ssh() as ssh_connection:
            with self._get_device_ssh(ssh_connection) as device_ssh:
                device_ssh.files.get(
                    f"/ffs/run/TargetBD_{self.sw_version}.xml",
                    dst_path,
                    timeout=30,
                )
        return dst_path

    @property
    def sw_version(self) -> str:
        """
        Gets full SW version from eNB, e.g. 'FL19_FSM4_9995_190221_000288'
        :return:
        """
        if not self._sw_version:
            self._sw_version = self._get_sw_version()
        return self._sw_version

    @property
    def sw_release(self) -> str:
        """
        Get only SW release, e.g. 'FL19'
        Also sets full sw_version
        :return:
        """
        return self.sw_version.split("_")[0]

    @abstractmethod
    def _get_vlan_id(self):
        pass

    def reset_if_only_rad_params(self):
        if self._rad_reset_required:
            self.logger.debug("R&D reset required")
            super().reset()

    def perform_full_commissioning(self, recovery: bool) -> None:
        try:
            return self._perform_full_commissioning()
        except Exception as err:
            if not recovery:
                raise
            self.logger.debug(err)
            self.logger_recovery.info(err)
            self._get_recovery_snapshot()
            self._recovery_for_commissioning()
            return self._perform_full_commissioning()

    def _perform_full_commissioning(self):
        try:
            self.logger.info(f"Original SCFC path = {self.scfc_path}")
            self.configure_scfc()
            self.logger.info(f"Starting full commissioning with file {self.scfc_path} for BTS-{self.bts_id}")
            alias = self._create_alias("perform_full_commissioning")
            with bts_admin_access(
                alias=alias,
                host=self.lmp_ip,
                remote_host=self.remote_host,
                port=443,
                output_dir=self.output_directory_path,
                logger=self.logger,
                release=self.sw_release,
            ) as new_admin_connection:
                if self.vendor_params:
                    self.logger.debug(f"Modyfing vendor params: {self.vendor_params}")
                    new_admin_connection.download_vendor_file(
                        pathlib.Path(self.output_directory_path, "vendor.xml").as_posix(),
                        alias=alias,
                    )
                    modified_vendor_path = VendorModifier(self.vendor_params, self.output_directory_path).modify()
                    new_admin_connection.set_vendor_file(
                        modified_vendor_path.as_posix(),  # todo !=PY27: pure pathlib
                        alias=alias,
                    )
                new_admin_connection.perform_commissioning(
                    bts_id=self.bts_id,
                    scf_file=self.scfc_path,
                    timeout=self._commissioning_timeout,
                    skip_parameter_relation_errors=True,
                    alias=alias,
                )
            self.logger.info(f"Full commissioning done for eNB {self.bts_id}!")
            self._rad_reset_required = False
        except Exception as exc:
            self.logger.debug(exc, exc_info=True)
            raise

    @contextmanager
    def scfc_file(self) -> Generator[Scfc, None, None]:
        scfc = Scfc(self.scfc_path)
        yield scfc
        modified_scfc_path = pathlib.Path(
            self.output_directory_path,
            f"MODIFIED_{pathlib.Path(self.scfc_path).name}",
        ).as_posix()
        self.scfc_path = modified_scfc_path
        scfc.save(modified_scfc_path)
        self.logger.info(f"Modified SCFC saved under {modified_scfc_path}")

    def configure_scfc(self) -> None:
        self._modify_vlans(self.scfc_data)
        orig_scfc_path = pathlib.Path(self.scfc_path)
        new_path = pathlib.Path(self.output_directory_path, f"MODIFIED_{orig_scfc_path.name}")
        save_dict_to_xml(self.scfc_data, new_path)
        self.scfc_path = new_path.as_posix()

    def _modify_vlans(self, scfc_data: dict) -> None:
        if not self.vlan_id:
            return
        self.logger.info(f"Going to modify vlan to {self.vlan_id}")
        vlanifs_to_create, vlanifs_to_modify = self._get_vlanifs_to_manipulate(scfc_data)
        self.logger.debug(f"{vlanifs_to_create = }, {vlanifs_to_modify = }")
        check_and_remove_existing_vlans(vlanifs_to_create, scfc_data, self.logger)
        create_new_vlan_mo(vlanifs_to_create, self.vlan_id, scfc_data)
        modify_existing_vlan_mo(vlanifs_to_modify, self.vlan_id, scfc_data)

    @staticmethod
    def _get_vlanifs_to_manipulate(scfc_data: dict) -> tuple[list[str], list[str]]:
        ipv4_data = get_ipv4_bts_data(scfc_data)
        ipv6_data = get_ipv6_bts_data(scfc_data)
        ipv4_local_nets = get_ipv4_local_networks()
        ipv6_local_nets = get_ipv6_local_networks()
        ipifs_v4_to_modify = get_ipifs_to_modify(ipv4_data, ipv4_local_nets)
        ipifs_v6_to_modify = get_ipifs_to_modify(ipv6_data, ipv6_local_nets)
        return get_vlanifs(ipifs_v4_to_modify, ipifs_v6_to_modify, scfc_data)

    def update_rad_parameters(self) -> None:
        with self._get_remote_host_ssh() as ssh_connection:
            try:
                self._update_rad_parameters(ssh_connection)
            except Exception as err:
                self.logger.debug(err, exc_info=True)
                self.logger_recovery.info(err)
                self.recover_ssh(ssh_connection)
                self._update_rad_parameters(ssh_connection)

    def _update_rad_parameters(self, ssh_connection: SSHConnection):
        self.logger.debug("Update R&D parameters started")
        if self.rad_params is None:
            self.logger.debug("No R&D parameters to set")
            return
        with self._get_device_ssh(ssh_connection) as device_ssh:
            if not isinstance(self.rad_params, pathlib.Path):
                swconfig = self._get_swconfig(device_ssh)
                sw = Swconfig(swconfig)
                swconfig = sw.modify_swconfig(self.rad_params)
            else:
                swconfig = self.rad_params.as_posix()
            self._put_modified_swconfig(swconfig, device_ssh)
            self._remove_old_swconfig_signature_file(device_ssh)
            self._create_swconfig_signature(device_ssh)
            self._verify_swconfig_signature(device_ssh)
        self.logger.info("R&D parameters updated")
        self._rad_reset_required = True

    def recover_ssh(self, ssh_connection: Optional[SSHConnection] = None) -> None:
        if ssh_connection is None:
            with self._get_remote_host_ssh() as ssh_connection:
                self._recover_ssh(ssh_connection)
        else:
            self._recover_ssh(ssh_connection)

    def _recover_ssh(self, ssh_connection: SSHConnection) -> None:
        for attempt_no in range(1, 3):
            try:
                self._wait_until_host_is_available(ssh_connection, 30)
                with bts_admin_access(
                    bts_admin_alias := self._create_alias("recover_enb_ssh"),
                    host=self.lmp_ip,
                    remote_host=self.remote_host,
                    output_dir=self.output_directory_path,
                    logger=self.logger,
                ) as admin_access:
                    self._enable_service_account_ssh(admin_access, bts_admin_alias)
                    self._enable_r_n_d_service_port(admin_access, bts_admin_alias)
                    self._disable_ethernet_port_security(admin_access, bts_admin_alias)
                    self._disable_system_acct_perm_enable(admin_access, bts_admin_alias)
                self._wait_for_host_ssh(ssh_connection, timeout=60)
                self.logger.debug("SSH on BTS should be recovered")
                return
            except HostSSHUnavailable:
                self.logger.debug("SCFC has SSH disabled")
                raise
            except Exception as err:
                if attempt_no == 2:
                    self.logger.debug(f"_recovery_update_rad_parameters failed on device\n{self}")
                    raise
                self.logger.debug(err)
                self._wait_until_constant_pingable(ssh_connection)

    def _set_bts_name(self, scfc: Scfc) -> None:
        tl_name = f"{get_tl_name()}-{self.bts_id}"
        scfc.set_bts_name(tl_name)
        self.logger.debug(f"Updated BTS Name to {tl_name} for enb")

    def _get_swconfig(self, device_ssh: ProxySSHConnection) -> str:
        swconfig_destination = pathlib.Path(self.output_directory_path, "swconfig.txt").as_posix()
        device_ssh.files.get("/ffs/run/swconfig.txt", swconfig_destination, timeout=30)
        self.logger.debug(f"Swconfig saved at {swconfig_destination}")
        return swconfig_destination

    def _put_modified_swconfig(self, swconfig: str, device_ssh: ProxySSHConnection) -> None:
        device_ssh.files.put(swconfig, "/ffs/run/swconfig.txt", timeout=30)
        self.logger.debug("Swconfig put to eNB")

    def _create_swconfig_signature(self, device_ssh: ProxySSHConnection) -> None:
        command = "crasign /ffs/run/swconfig.txt"
        device_ssh.execute(command, timeout=30)
        self.logger.debug("Swconfig signature file created")

    def _verify_swconfig_signature(self, device_ssh: ProxySSHConnection) -> None:
        command = "craverify /ffs/run/swconfig.txt /ffs/run/swconfig.txt.p7 1>&2"
        cmd = device_ssh.send_command(command, timeout=30)
        if cmd.get_exit_code() != 0:
            raise SignatureFailure("swconfig signature is not valid")
        self.logger.debug("swconfig signature is verified")

    def _remove_old_swconfig_signature_file(self, device_ssh: ProxySSHConnection) -> None:
        command = "rm /ffs/run/swconfig.txt.p7"
        try:
            device_ssh.execute(command, timeout=30)
        except Exception as err:
            self.logger.debug(err)
        self.logger.debug("Old swconfig signature file removed")

    def _get_sw_version(self) -> str:
        with self._get_remote_host_ssh() as ssh_connection:
            with self._get_device_ssh(ssh_connection) as device_ssh:

                def __get_sw_ver():
                    filebd = device_ssh.execute(command="ls -1 /ffs/run/TargetBD*.xml", timeout=15)
                    self.logger.debug(f"FILEBD: {filebd.strip()}")
                    for res in re.finditer("(SBTS|[FT]L|5G)[0-9A-Z_.]+", filebd):
                        return res.group(0).strip(".")
                    raise AttributeError("Cannot get SW version from TargetBD file")

                try:
                    return __get_sw_ver()
                except Exception as err:
                    self.logger.debug(f"Error while getting SW version: {type(err)}:{err}")
                    self.recover_ssh(ssh_connection)
                    return __get_sw_ver()

    @bts_is_on
    def wait_for_rmods_up(self, timeout: float) -> None:
        if self._is_secondary_smod:
            return
        rmod_count = self.get_rmods_count()
        alias = f"check_for_rmods_{self.remote_host}"
        with bts_admin_access(
            alias,
            host=self.lmp_ip,
            remote_host=self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as new_admin_access:
            self.logger.debug(f"Start waiting for {rmod_count} rmods on enb {repr(self)}")
            self._check_rmods(timeout, rmod_count, alias, new_admin_access)

    def _cache_bts_info(self, alias: str, new_admin_acces: admin, timeout: float) -> None:
        """Caching BTS info in node.js to allow fast rmods checking."""
        self._get_bts_info(alias, new_admin_acces, timeout)

    def _check_rmods(self, timeout, rmod_count, alias, new_admin_access):
        start_time = time.time()
        sync_status = False
        self._cache_bts_info(alias, new_admin_access, timeout)
        while (time.time() - start_time) < timeout:
            try:
                sync_status = self._check_synchronization(new_admin_access, alias, get_time_diff(start_time, timeout))
                if not self._are_rmods_enabled(rmod_count, alias, new_admin_access, get_time_diff(start_time, timeout)):
                    time.sleep(5)
                    continue
                self.logger.info(
                    "Total rmod count: {} for eNB on remote host: {} detected after: {}".format(
                        rmod_count, self.remote_host, time.time() - start_time
                    )
                )
                return
            except Exception as err:
                self.logger.debug(f"{type(err).__name__}: {err}")
        else:
            if not sync_status:
                raise SynchronizationFailure("No sync on eNB. Preferred option is GPS (GNSSE) with `actGnssOutputLnaPowerSupply` set to True.")
            else:
                raise RmodDetectionTimeout(
                    "Rmods not detected in time: {}. Please check synchronization status. "
                    "Preferred option is GPS (GNSSE) with `actGnssOutputLnaPowerSupply` set to True.".format(timeout)
                )

    def _are_rmods_enabled(self, rmod_count: str, alias: str, admin_access: admin, timeout: float) -> bool:
        rmod_up_count = -1
        rmods = admin_access.get_parameters_for_all("RMOD", alias=alias, timeout=timeout)
        if rmods:
            rmods_states = [
                True for rmod in rmods if rmod["operationalState"].lower() == "enabled" and rmod["administrativeState"].lower() == "unlocked"
            ]
            rmod_up_count = len(rmods_states)
        self.logger.debug(f"number of radios currently available : {rmod_up_count} vs expected: {rmod_count}")
        return rmod_up_count == rmod_count

    @bts_is_on
    def ensure_on_air_state(self, timeout: int = 600) -> None:
        if self._is_secondary_smod:
            return
        alias = f"mrbs_state_{self.remote_host}"
        start_time = time.time()
        with bts_admin_access(
            alias,
            host=self.lmp_ip,
            remote_host=self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as admin_access:
            while (time.time() - start_time) < timeout:
                try:
                    assert self._get_mrbs_state(alias, admin_access, get_time_diff(start_time, timeout)).lower() == "onair"
                    bts_info = self._get_bts_info(alias, admin_access, timeout=get_time_diff(start_time, timeout))
                    for technology in ["lte", "nr"]:
                        for cell in bts_info["cells"][technology]:
                            self.logger.debug(
                                "{} cell with PCI-{} operationalState: {}".format(
                                    technology.upper(),
                                    cell["physicalCellId"],
                                    cell["status"]["operationalState"],
                                )
                            )
                    break
                except AssertionError:
                    time.sleep(5)
            else:
                raise ValueError("MRBTS state is not onair as expected.")

    def _get_bts_info(self, alias: str, admin_access: admin, timeout: float) -> dict:
        bts_info = {}
        try:
            bts_info = admin_access.get_bts_info(alias=alias, timeout=timeout)
        except Exception as e:
            self.logger.debug(f"Exception caught within '_get_bts_info': {e}")
        return bts_info

    def _get_mrbs_state(self, alias: str, admin_access: admin, timeout: float) -> str:
        state = ""
        try:
            state = str(admin_access.get_mrbts_state(alias=alias, timeout=timeout)).lower()
            self.logger.debug(f"Retrieved MRBTS state: {state}")
        except Exception as e:
            self.logger.warning(
                f"Exception caught withing 'get_mrbts_state': {e}",
                exc_info=True,
            )
        return state

    @log_function
    def _enable_service_account_ssh(self, admin_access, alias):
        admin_access.enable_ssh_access(alias=alias)

    @log_function
    def _enable_r_n_d_service_port(self, admin_access, alias):
        admin_access.change_rnd_port_security(enable=True, alias=alias)

    @log_function
    def _disable_ethernet_port_security(self, admin_access, alias):
        admin_access.disable_ethernet_port_security(alias=alias)

    def reset(self):
        self._get_recovery_snapshot()
        super().reset()

    def _get_recovery_snapshot(self):
        if not self._user_flags.get("recovery_snapshot", False):
            self.logger.debug("Recovery snapshot disabled.")
            return
        alias = "recovery_snapshot"
        with bts_admin_access(
            alias,
            host=self.lmp_ip,
            remote_host=self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as admin_access:
            timestamp = datetime.now().strftime("%Y_%m_%d__%H_%M")
            snapshot_path = pathlib.Path(self.output_directory_path, f"snapshot_{timestamp}.zip")
            try:
                self.logger.debug("Trying to gather recovery snapshot")
                admin_access.get_snapshot(snapshot_path.as_posix(), connection=alias)
                self.logger.debug("Recovery snapshot gathered")
            except Exception as err:
                self.logger.warning(err)

    def _recovery_for_commissioning(self, retry_attempt=1):
        self.logger.debug(f"Starting recovery for commissioning. Attempt number {retry_attempt}")
        try:
            with self._get_remote_host_ssh() as ssh_connection:
                self.wait_for_interfaces_and_ssh(skip_unavailable=True, ssh_connection=ssh_connection)
                self._reset_config_and_rebot_via_ssh(ssh_connection)
                self._wait_until_constant_pingable(skip_reset=True, ssh_connection=ssh_connection)
                self._wait_for_bbus_or_smods(self._create_alias("recovery_for_commissioning"))
                self.recover_ssh(ssh_connection)
                self.logger.debug("Recovery for commissioning ok")
        except Exception as err:
            self.logger.debug(err)
            if retry_attempt == 2:
                raise
            self.reset()
            self._recovery_for_commissioning(retry_attempt=2)

    def _reset_config_and_rebot_via_ssh(self, ssh_connection: SSHConnection, attempt_no: int = 1) -> None:
        try:
            with self._get_device_ssh(ssh_connection) as device_ssh:
                self._remove_configs_via_ssh(device_ssh)
                self._reboot_via_ssh(device_ssh)
            self._set_default_lmp_ip()
        except Exception as err:
            self.logger.debug(f"Error while resetting config: {type(err)}:{err}")
            if attempt_no == 1:
                self._reset_lmp_ip()
            elif attempt_no == 2:
                self.swap_lmp_for_secondary_bts()
            elif attempt_no == 3:
                self._set_default_lmp_ip()
            else:
                raise ConnectionFailure(f"Cannot connect to BTS neither on {self.lmp_ip} or 192.168.255.119")
            return self._reset_config_and_rebot_via_ssh(ssh_connection, attempt_no=attempt_no + 1)

    def _reboot_via_ssh(self, device_ssh: ProxySSHConnection) -> None:
        try:
            self.logger.debug("Going to reboot ENB")
            device_ssh.execute("reboot", timeout=15)
            self.logger.debug("ENB rebooted.")
        except Exception as err:
            self.logger.debug("Cannot reboot ENB, probably rebooted after config files removed.")
            self.logger.debug(f"{type(err)}:{err}", exc_info=True)

    def _remove_configs_via_ssh(self, device_ssh: ProxySSHConnection):
        try:
            self.logger.debug("Removing config in a hard way (via SSH).")
            device_ssh.execute(
                r'bash -ce "cd /ffs/run/config/; '
                r"find . ! -path ./toor4nsn ! -path ./toor4nsn/\* "
                r"! -path ./serviceuser ! -path ./serviceuser/\* "
                r"! -path ./fsp_mma.txt ! -path ./fsp_mma.txt.sig "
                r"! -path ."
                r' -exec rm -rf {} +"',
                timeout=15,
            )
            self.logger.debug("Configuration files removed")
        except Exception as err:
            self.logger.debug(f"Error while removing config files: {type(err)}:{err}")

    def _wait_for_bbus_or_smods(self, alias: str, timeout: int | float = 60 * 10):
        with bts_admin_access(
            alias,
            host=self.lmp_ip,
            remote_host=self.remote_host,
            output_dir=self.output_directory_path,
            logger=self.logger,
            release=self.sw_release,
        ) as admin_access:
            start_time = time.time()
            while (time.time() - start_time) < timeout:
                try:
                    modules_states = self._get_enb_modules_state(admin_access, alias, get_time_diff(start_time, timeout))
                    self.logger.info(f"ADMIN: Reached states: {modules_states}")
                    assert set(modules_states) == {"enabled"}, f"Not all modules active: {modules_states}"
                    return
                except AssertionError:
                    pass
                except Exception as err:
                    self.logger.debug(err)
                time.sleep(5)
        raise ModuleActiveFailure()

    def _get_enb_modules_state(self, admin_access: admin, alias: str, timeout: float):
        bts_info = self._get_bts_info(alias, admin_access, timeout)
        modules = bts_info["basebandModules"] if bts_info["basebandModules"] else bts_info["systemModules"]
        modules_states = [module["status"]["operationalState"].lower() for module in modules]
        self.logger.debug(f"ADMIN: Modules state: {modules_states} of node {self.bts_id}")
        return modules_states

    @staticmethod
    def _wait_for_enb_to_finish_configuration_and_reset():
        time.sleep(30)

    def _disable_system_acct_perm_enable(self, admin_access: admin, alias: str) -> None:
        try:
            scf = admin_access.get_scf("configuration", timeout=60, alias=alias)
        except Exception as err:
            # todo check proper exception type, probably taf.admin.AdminApiProcedureFailureException
            self.logger.debug(f"No SCF - probably configuration is wiped out :: {type(err)}:{err}")
            return
        if match_object := re.search(r'systemAcctPermEnable">(.*)</p>', scf):
            if opt_bool(match_object.group(1)) is True:
                admin_access.perform_parameter_recommissioning(
                    "MRBTS-1/MNL-1/MNLENT-1/FEATCADM-1",
                    "systemAcctPermEnable",
                    "update",
                    "false",
                    True,
                    alias=alias,
                )
        else:
            self.logger.debug("No 'systemAcctPermEnable' in SCF. If SCF is not older than xL18A it should not happen.")

    def _check_synchronization(self, admin_access: admin, alias: str, timeout: float):
        try:
            sync_source_status = admin_access.get_bts_sync_source_status(connection=alias, timeout=timeout)
            self.logger.debug(f"Synchronization status: {sync_source_status}")
            return any(is_active for sync_info in sync_source_status["syncSourceInfo"] if (is_active := sync_info["isActive"]))
        except Exception as err:
            self.logger.debug(err)
        return False

    def set_commissioning_timeout(self, timeout_value: int):
        self._commissioning_timeout = timeout_value


@contextmanager
def bts_admin_access(
    alias: str,
    host: str = "192.168.255.129",
    remote_host: str = "127.0.0.1",
    port: int = 443,
    output_dir: str = "/tmp/",
    logger: logging.Logger | MagicMock = MagicMock(),
    release: str | None = None,
) -> Generator[admin, None, None]:
    taf_admin_instance = admin()
    connected = False
    for counter in range(3):
        try:
            logger.debug(f"SETUP START: BTS_ADMIN: [{host}, {remote_host}, {alias}, {port}, {output_dir} {release}]")
            taf_admin_instance.setup_admin(
                bts_host=host,
                bts_port=port,
                use_ssl=True,
                admin_api_log_dir=output_dir,
                remote_host=remote_host,
                alias=alias,
                release=release,
            )
            connected = True
            logger.debug(f"SETUP DONE: BTS_ADMIN: [{host}, {remote_host}, {alias}, {port}, {output_dir} {release}]")
            yield taf_admin_instance
            break
        finally:
            try:
                if not connected:
                    logger.debug(f"TEARDOWN NOT NEEDED: BTS_ADMIN: [{host}, {remote_host}, {alias}, {port}, {output_dir} {release}]")
                    if counter < 2:
                        logger.debug("Going to sleep for 10 and retry connection")
                        time.sleep(10)
                        continue
                else:
                    logger.debug(f"TEARDOWN START: BTS_ADMIN: [{host}, {remote_host}, {alias}, {port}, {output_dir} {release}]")
                    taf_admin_instance.teardown_admin(alias=alias)
                    logger.debug(f"TEARDOWN DONE: BTS_ADMIN: [{host}, {remote_host}, {alias}, {port}, {output_dir} {release}]")
            except Exception as exc:
                if aliases := taf_admin_instance.store.all:
                    logger.error(f"Aliases still in store: {aliases}. Please check `node` and kill them all.")
                logger.warning(exc)
                raise


@contextmanager
def bts_infomodel_access(
    alias: str,
    host: str = "192.168.255.129",
    remote_host: str = "127.0.0.1",
    port: int = 3600,
    output_dir: str = "/tmp/",
    logger: logging.Logger | MagicMock = MagicMock(),
) -> Generator[ute_admin_infomodel, None, None]:
    im_instance = ute_admin_infomodel()
    try:
        logger.debug(f"SETUP START: BTS_INFOMODEL: [{host}, {remote_host}, {alias}, {port}, {output_dir}]")
        im_instance.setup_infomodel(address=host, port=port, remote_host=remote_host, alias=alias, admin_api_log_dir=output_dir)
        im_instance.connect_infomodel(alias=alias)
        logger.debug(f"SETUP DONE: BTS_INFOMODEL: [{host}, {remote_host}, {alias}, {port}, {output_dir}]")
        yield im_instance
    finally:
        try:
            logger.debug(f"TEARDOWN START: BTS_INFOMODEL: [{host}, {remote_host}, {alias}, {port}, {output_dir}]")
            im_instance.disconnect_infomodel(alias=alias)
            im_instance.teardown_infomodel(alias=alias)
            logger.debug(f"TEARDOWN DONE: BTS_INFOMODEL: [{host}, {remote_host}, {alias}, {port}, {output_dir}]")
        except Exception as exc:
            logger.warning(exc)
